#include <stdio.h>

int main() {
    // 计算数字位数
    int n, count = 0;
    scanf("%d", &n);
    while (n > 0) {
        n /= 10;
        count++;
    }
    printf("位数:%d\n", count);
    return 0;
}

#include <stdio.h>

int main() {
    int num;
    do {
        printf("输入1-7之间的数字: ");
        scanf("%d", &num);
    } while (num < 1 || num > 7);
    printf("你输入了: %d\n", num);
    return 0;
}

