#include <stdio.h>

int main() {
    for (int i = 1; i <= 9; i++) {
        for (int j = 1; j <= i; j++) {
            printf("%d*%d=%-2d ", j, i, i*j);
        }
        printf("\n");
    }
    return 0;
}

// 综合示例：菜单系统
#include <stdio.h>
int main() {
    int choice;
    do {
        printf("1.开始 2.设置 3.退出\n");
        scanf("%d", &choice);
        switch(choice) {
            case 1: printf("游戏开始\n"); break;
            case 2: printf("设置中\n"); break;
            case 3: printf("再见\n"); break;
        }
    } while(choice != 3);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>

int main() {
    srand((unsigned)time(NULL));
    int target = rand() % 100 + 1;
    int guess, count = 0;
    do {
        printf("猜一个1-100的数: ");
        scanf("%d", &guess);
        count++;
        if (guess > target) printf("大了\n");
        else if (guess < target) printf("小了\n");
        else printf("猜中了！用了%d次\n", count);
    } while (guess != target);
    return 0;
}
